INSERT INTO reviews (id, product_id, reviewer_name, rating, review_date, title, content, helpful_count, verified_purchase) VALUES
  ('223e4567-e89b-12d3-a456-426614174001', '123e4567-e89b-12d3-a456-426614174000', '田中太郎', 5, '2025-03-15', '最高のエンジンオイル', 'このプレミアムエンジンオイルを使い始めてから、エンジンの調子が格段に良くなりました。始動時のノイズが減り、燃費も向上しました。特に寒い朝のエンジンスタートがスムーズになったのが印象的です。価格は少し高めですが、その価値は十分にあります。次回もリピート購入する予定です。', 42, true),
  ('223e4567-e89b-12d3-a456-426614174002', '123e4567-e89b-12d3-a456-426614174000', '佐藤健', 4, '2025-02-28', '品質は良いが価格が高い', '品質面では申し分ないエンジンオイルです。エンジンの動きがスムーズになり、静かになりました。ただ、価格が他のブランドと比べて20%ほど高いのが気になります。長期的に見れば燃費向上やエンジン寿命の延長につながるかもしれませんが、もう少し手頃な価格だと嬉しいです。それでも品質重視の方にはおすすめできます。', 18, true),
  ('223e4567-e89b-12d3-a456-426614174003', '123e4567-e89b-12d3-a456-426614174000', '鈴木一郎', 5, '2025-01-10', '冬場の性能が素晴らしい', '北海道在住です。厳しい冬の寒さでも、このオイルのおかげでエンジンの始動に問題ありません。-15℃の朝でもすぐにエンジンがかかります。以前使っていた他社製品では冷間始動時にエンジンが唸るような音がしていましたが、このオイルに変えてからはそれがなくなりました。寒冷地にお住まいの方には特におすすめです。耐久性も良く、5000km走行後も性能の低下を感じません。', 35, true),
  
  ('223e4567-e89b-12d3-a456-426614174004', '123e4567-e89b-12d3-a456-426614174001', '山田花子', 5, '2025-03-20', 'スポーツ走行に最適', 'スポーツカーに使用していますが、高回転域でのエンジンレスポンスが明らかに向上しました。熱安定性も高く、サーキット走行後も性能が落ちません。他のオイルと比較しても明らかに違いを感じます。価格は高めですが、パフォーマンスを重視する方には間違いなくおすすめできます。', 27, true),
  ('223e4567-e89b-12d3-a456-426614174005', '123e4567-e89b-12d3-a456-426614174001', '伊藤誠', 4, '2025-02-15', '高性能だが交換頻度が気になる', '性能面では非常に満足しています。エンジン音が静かになり、加速もスムーズになりました。ただ、メーカー推奨の交換頻度が5000kmと短めなのが少し不便です。長距離ドライバーには少し手間かもしれません。それでも性能を考えれば納得できる交換頻度だと思います。', 15, true),
  
  ('223e4567-e89b-12d3-a456-426614174006', '123e4567-e89b-12d3-a456-426614174002', '高橋裕子', 3, '2025-03-05', 'コスパは良いが性能は平均的', '価格が手頃なので購入しました。燃費は若干向上したように感じますが、劇的な変化はありません。エンジン音や振動の低減効果も平均的です。コストパフォーマンスを重視する方には良いと思いますが、性能にこだわる方は他の選択肢も検討した方が良いかもしれません。', 8, true),
  ('223e4567-e89b-12d3-a456-426614174007', '123e4567-e89b-12d3-a456-426614174002', '小林健太', 4, '2025-02-20', '普段使いには十分な性能', '通勤用の軽自動車に使用していますが、十分な性能です。始動性も良く、特に問題は感じません。価格も手頃で、定期的な交換も経済的に続けられそうです。特別なパフォーマンスは期待していませんが、日常使いには最適なオイルだと思います。', 12, true),
  
  ('223e4567-e89b-12d3-a456-426614174008', '123e4567-e89b-12d3-a456-426614174003', '中村洋介', 5, '2025-03-25', '交換頻度が少なくて助かる', '10000kmの交換間隔が魅力で購入しました。実際に使用してみると、長距離走行でも性能が安定しています。エンジンの調子も良く、オイル消費も少ないです。頻繁にオイル交換する時間がない方や、長距離運転が多い方にはとてもおすすめです。コスト的にも結果的に経済的だと思います。', 31, true),
  ('223e4567-e89b-12d3-a456-426614174009', '123e4567-e89b-12d3-a456-426614174003', '加藤美咲', 4, '2025-02-10', '安定した性能で信頼できる', '古い車に使用していますが、エンジンの調子が良くなりました。特に高速道路での走行時にエンジンの安定感が増したように感じます。交換頻度も少なくて済むので、メンテナンスの手間が減りました。ただ、低温時の始動性は他のオイルと比べるとやや劣る印象です。それ以外は満足しています。', 19, true),
  
  ('223e4567-e89b-12d3-a456-426614174010', '123e4567-e89b-12d3-a456-426614174004', '渡辺隆', 5, '2025-03-18', 'サーキット走行に最適', 'サーキット走行用に購入しました。高回転、高負荷状態でも安定した性能を発揮します。エンジンの応答性が向上し、パワーも若干アップしたように感じます。熱安定性も非常に高く、連続走行後もオイルの劣化が少ないです。価格は高めですが、スポーツ走行を楽しむ方には間違いなく価値があります。', 24, true),
  ('223e4567-e89b-12d3-a456-426614174011', '123e4567-e89b-12d3-a456-426614174004', '松本健太', 4, '2025-02-25', '高性能だが一般道では過剰かも', 'スポーツカーに使用していますが、性能は申し分ありません。エンジンの回りが良くなり、高回転域でのレスポンスが向上しました。ただ、普段の街乗りだけなら少しオーバースペックな気もします。サーキット走行や峠道を楽しむ方には最適ですが、一般的な使用なら他の選択肢もあると思います。それでも品質は最高レベルです。', 16, true);